 function jobs(list=data.jobs){return list.length?list.map(j=>`<article class="panel ls-section" data-op-job="${h(j.id)}"><div class="ls-lead-head"><h3>#${j.id} · ${h(j.title)}</h3><span class="badge">${h(names[j.state]||j.state)}</span></div><p>${h(accountName(j.account))} · ${h({post:'Публикация',message:'Сообщение людям',invite:'Добавление участников',link:'Ссылка-приглашение',invite_message:'Личное приглашение'}[j.kind])} · ${stamp(j.created)}</p>${retryHistory(j)}${pilotNotice(j)}${window.OperationPreview?.jobView?.(j)||''}<p>Получателей: ${j.items.length}.</p>${j.kind==='invite'?'<p class="small">Прямое добавление в группу. Личные сообщения и ссылки участникам не отправляются. Если Telegram запретит добавление, панель сохранит отказ.</p>':''}${j.not_before?`<p>Следующее действие не ранее: ${stamp(j.not_before)}</p>`:''}<p class="pub-post-text">${h(j.spec.text)}${j.kind==='invite_message'?'\n\n'+h(j.spec.invite_url):''}</p>${(j.spec.media||[]).map(id=>`<img src="${base}/media/${encodeURIComponent(String(id))}" alt="Фото задания" width="100">`).join('')}${j.kind==='invite'&&j.spec.add_contacts_before_invite?'<p class="small">Подготовка контакта включена. В обычном режиме ошибка сохранения не отменяет отдельную прямую попытку. В одиночной проверке требование взаимного контакта определяется выбранным режимом. Ограничения Telegram останавливают действия; сохранение само по себе не означает вступление.</p>':''}<p class="small">Пауза: ${j.spec.delay_seconds} сек. · ${j.pilot?'Обычный дневной предел без разового допуска':'Дневной предел'}: ${j.spec.daily_limit}</p><div class="pub-delivery">${j.items.map(i=>`<div><strong>${h(i.chat_title)}</strong>${i.user_name?` → @${h(i.user_name)}`:i.user_id?` → ID ${h(i.user_id)}`:''}<span>${h(names[i.state]||i.state)}</span>${i.error&&(i.state==='pending'||!i.diagnosis?.reason)?`<p class="ls-error">${h(i.error)}</p>`:''}${itemDiagnosis(i)}${membershipView(j,i)}${i.state==='restricted'&&!i.retryable&&i.retry_reason?`<p class="small">${h(i.retry_reason)}</p>`:''}${i.invite_link?`<p><a href="${h(i.invite_link)}" target="_blank" rel="noopener noreferrer">${h(i.invite_link)}</a></p>`:''}${(i.links||[]).map(l=>`<a href="${h(l)}" target="_blank" rel="noopener noreferrer">Открыть публикацию</a>`).join(' ')}</div>`).join('')}</div>${singleView(j)}${canContinuePending(j)?'<p class="notice">Продолжение обработает только ожидающих участников. Отказы и неподтверждённые результаты сохранятся, повторного приглашения этим людям не будет.</p>':''}${['draft','paused'].includes(j.state)||j.kind==='post'&&j.items.some(i=>i.state==='sent')?`<label><input type="checkbox" data-confirm-job="${j.id}"> ${h(j.kind==='invite'?'Проверил аккаунт, группу и участников; подтверждаю прямое добавление без личных сообщений.':j.kind==='link'?'Проверил аккаунт, группу и параметры ссылки; подтверждаю создание ссылки.':'Проверил отправителя, текст и получателей; подтверждаю выбранное действие.')}</label>`:''}<div class="ls-actions">${j.state==='draft'?button('Подтвердить запуск','start',j.id):''}${['queued','scheduled'].includes(j.state)?button('Пауза','pause',j.id):''}${j.state==='paused'&&(!j.single_attempt||j.single_attempt.state==='released')&&!j.pilot?.goal_met&&j.items.some(i=>i.state==='pending')&&!j.items.some(i=>i.state==='sending')?(canContinuePending(j)?button('Продолжить остальных без повтора','continue_pending',j.id):button('Возобновить','resume',j.id)):''}${canContinueSingle(j)?button('Продолжить остальных','continue-after-single',j.id):''}${['draft','queued','scheduled','paused'].includes(j.state)?button('Отменить неотправленное','cancel',j.id):''}${j.kind==='post'&&!['queued','scheduled'].includes(j.state)&&j.items.some(i=>i.state==='sent')&&!j.items.some(i=>i.state==='sending')?button('Удалить публикации задания','remove-messages',j.id):''}<a class="button secondary" href="${base}/jobs/${j.id}/report">Скачать CSV</a></div>${retryForm(j)}${window.OperationCampaigns?.jobView(j)||''}${window.OperationTracking?.jobView(j)||''}</article>`).join(''):'<section class="panel ls-section">Заданий пока нет. Сначала подключите аккаунт и сохраните черновик.</section>';}
 function mergeJobHistory(details=[]){for(const j of details)historyJobs.set(j.id,j);if(details.length){const fresh=new Map(details.map(j=>[j.id,j]));latestJobs=latestJobs.map(j=>fresh.get(j.id)||j);}data.jobs=[...new Map([...historyJobs.values(),...latestJobs].map(j=>[j.id,j])).values()].sort((a,b)=>b.id-a.id);}
 function jobReviewIdentity(j){return j?JSON.stringify([j.account,j.telegram_id,data.accounts.filter(a=>a.id===j.account).map(a=>[a.telegram_id,a.connection,a.enabled]),j.kind,j.state,j.spec,j.single_attempt,j.items.map(i=>[i.id,i.chat_id,i.user_id,i.user_name,i.state])]):'';}
