 function historyView(){const groups=data.invite_summary?.groups||[],known=groups.some(g=>String(g.chat_id)===history.chatId);return `<section class="panel ls-section" data-op-history style="min-width:0;overflow-wrap:anywhere"><h2>История заданий</h2><form id="op-history-filters" data-version="${history.version}"><div style="display:flex;gap:12px;flex-wrap:wrap;align-items:end"><label class="ls-field" style="flex:1 1 180px;min-width:0">Тип заданий<select id="op-history-kind" name="kind" aria-label="Тип заданий"><option value=""${!history.kind?' selected':''}>Все задания</option><option value="invite"${history.kind==='invite'?' selected':''}>Инвайтинг</option></select></label><label class="ls-field" style="flex:2 1 200px;min-width:0">Группа<select id="op-history-group" name="chat_id" aria-label="Группа"><option value="">Все группы</option>${history.chatId&&!known?`<option value="${h(history.chatId)}" selected>Группа ${h(history.chatId)}</option>`:''}${groups.map(g=>`<option value="${h(g.chat_id)}"${String(g.chat_id)===history.chatId?' selected':''}>${h(g.chat_title)}</option>`).join('')}</select></label></div><label style="display:block;margin:12px 0"><input id="op-history-pending" name="pending_only" type="checkbox"${history.pendingOnly?' checked':''}> Только с ожидающими получателями</label><div class="ls-actions"><button class="button" style="white-space:normal;max-width:100%">Показать задания</button>${history.chatId?button('Все группы','history-clear-group'):''}${history.active?button('Последние 100 заданий','history-recent'):''}${focusedAction?button('К настройке '+(focusedAction==='invite'?'инвайтинга':'рассылки'),'history-back'):''}</div></form><p class="small" data-op-history-status aria-live="polite">${history.active?(history.busy?'Загружаем историю…':history.loaded?'Загружено заданий: '+history.ids.length+'.'+(history.pendingOnly?' Показаны задания с ожидающими получателями. Изменившиеся после загрузки задания сохраняются до смены фильтра.':''):'История ещё не загружена.'):'Показаны последние 100 заданий. Фильтры открывают всю сохранённую историю.'}</p>${history.error?`<p class="ls-error" role="alert">${h(history.error)}</p>${button('Повторить загрузку истории','history-retry')}`:''}<p class="small muted">Карточки показывают задание целиком со всеми получателями. Просмотр и фильтры не запускают задания. Для старого черновика или задания на паузе нужны отдельная проверка и подтверждение под получателями.</p></section>`;}
